import sailpoint.object.Identity;
import sailpoint.object.Filter;
import sailpoint.api.SailPointContext;
import sailpoint.object.QueryOptions;

String department = (String) args.get("group");

if (department != null) {
    Filter deptFilter = Filter.eq("department", department);
    Filter mgrFilter = Filter.eq("title", "Manager");
    Filter combined = Filter.and(deptFilter, mgrFilter);

    QueryOptions qo = new QueryOptions();
    qo.addFilter(combined);

    List identities = context.getObjects(Identity.class, qo);

    if (identities != null && identities.size() > 0) {
        Identity owner = (Identity) identities.get(0);
        group.setOwner(owner);
        log.info("Group owner for department [" + department + "] set to: " + owner.getDisplayName());
    } else {
        log.warn("No manager found in department: " + department);
    }
} else {
    log.error("No department value provided for group owner assignment.");
}

return group;
